template:
fn take_header<'a>(data: ⟦slot1⟧) -> (⟦slot2⟧, &'a [u8]) {
    if data.len() < 4 {
        (&[], data)
    } else {
        (&data[..4], &data[4..])
    }
}

fn main() {
    let bytes = [1, 2, 3, 4, 5, 6];
    let (hdr, rest) = take_header(&bytes);
    println!("{}, {}", hdr.len(), rest.len());
}

tests:
#[test]
fn splits_bytes() {
    let input = vec![10, 20, 30, 40, 50];
    let (h, r) = take_header(&input);
    assert_eq!(h, &[10, 20, 30, 40]);
    assert_eq!(r, &[50]);
}
